def is_simple_power(x, n):
    if n == 1:
        return x == 1
    if n == -1:
        return x == 1 or x == -1
    if x == 1:
        return True
    if x == 0:
        return False
    if n == 0:
        return False

    import math
    if n > 0:
        if x <= 0:
            return False
        try:
            exponent = math.log(x) / math.log(n)
        except ValueError:
            return False
    else:
        if x > 0:
            return False
        try:
            exponent = math.log(abs(x)) / math.log(abs(n))
        except ValueError:
            return False

    if abs(exponent - round(exponent)) > 1e-10:
        return False

    int_exponent = round(exponent)

    if n > 0:
        return n ** int_exponent == x
    else:
        if int_exponent % 2 == 0:
            return (-n) ** int_exponent == x
        else:
            return -((-n) ** int_exponent) == x
</code>

